## Backend Selection Logic

```typescript
function selectBackend(resolved: ResolvedInstance, config: StoreConfig): StorageBackend {
  if (config.inMemory) {
    return createMemoryBackend();
  }

  if (resolved.isLegacy) {
    // Keep using TinyBase JSON for backward compat
    return createJsonBackend(resolved.instancePath);
  }

  // Default: SQLite
  return createSqliteBackendFromPath(resolved.instancePath);
}
```

