## Overview

Implement activity-based waking system that allows agents (especially Monitors) to wake on relevant events, plus the `wait_for_activity` MCP tool.

## Design: Multi-Scope Activity Relevance

### Relevance Algorithm

```typescript
function findRelevantAgents(activity: Activity): AgentId[] {
  const relevant = new Set<AgentId>();

  // 1. Lineage: Wake ancestors if event is from their subtree
  if (activity.source?.agent_id) {
    const ancestors = getLineage(activity.source.agent_id);
    ancestors.forEach(id => relevant.add(id));
  }

  // 2. Role-based: Check if event targets a role
  if (activity.target?.type === 'role') {
    const roleAgents = getAgentsByRole(activity.target.role);
    roleAgents.forEach(id => relevant.add(id));
  }

  // 3. Subscriptions: Check topic/broadcast subscribers
  if (activity.target?.type === 'topic') {
    const subscribers = getTopicSubscribers(activity.target.topic);
    subscribers.forEach(id => relevant.add(id));
  }

  // 4. Configurable event-type subscriptions
  const eventSubscribers = getEventTypeSubscribers(activity.type);
  eventSubscribers.forEach(id => relevant.add(id));

  // 5. Filter to active agents only
  return [...relevant].filter(id => isAgentActive(id));
}
```

### Configurable Event Subscriptions

Agents can subscribe to specific event types:
```typescript
interface EventSubscription {
  agentId: AgentId;
  eventTypes: EventType[];  // ['task_created', 'agent_terminated', etc.]
  scope?: {
    subtree?: AgentId;      // Only events from this subtree
    role?: string;          // Only events from agents with this role
  };
}
```

### Progressive Wake Strategy

```typescript
async function wakeAgent(
  agentId: AgentId,
  activity: Activity,
  priority: MessagePriority = 'normal'
): Promise<WakeResult> {
  const session = await getAgentSession(agentId);
  if (!session) {
    return { success: false, reason: 'no_session' };
  }

  const action = determineWakeAction(agentId, priority, session.isActive);

  switch (action) {
    case 'inject':
      if (await session.checkInjectSupport()) {
        const result = await session.inject(formatActivityContext(activity));
        if (result.success) return { success: true, method: 'inject' };
      }
      // Fall through to interrupt if inject not supported

    case 'interrupt':
      await session.interruptWith(formatActivityContext(activity));
      return { success: true, method: 'interrupt' };

    case 'wake':
      // Start new prompt with activity context
      await agentManager.prompt(agentId, formatActivityContext(activity));
      return { success: true, method: 'wake' };

    case 'queue':
      // Just ensure message is in queue, don't wake
      return { success: true, method: 'queued' };
  }
}
```

