function resolveRoleChannel(channel: RoleChannel): AgentId[] {
  let agents = eventStore.listAgents({ state: 'running' });

  // Filter by role
  agents = agents.filter(a => a.role === channel.role || a.role?.startsWith(channel.role + '.'));

  // Optional: scope to coordinator's subtree
  if (channel.coordinatorId) {
