function determineWakeAction(
  agentId: AgentId,
  priority: MessagePriority,
  hasActiveSession: boolean
): 'wake' | 'inject' | 'interrupt' | 'queue' {
  if (!hasActiveSession) {
    return priority === 'low' ? 'queue' : 'wake';
  }

  switch (priority) {
    case 'urgent': return 'interrupt';
    case 'high': return 'inject';
    case 'normal': return 'queue';
    case 'low': return 'queue';
  }
}
