export async function terminateWithChangeConsolidation(
  childId: AgentId,
  parentId: AgentId,
  agentManager: CascadeAgentManager,
  workspaceManager?: WorkspaceManager
): Promise<ConsolidationResult> {
  // 1. Get workspaces
  const childWorkspace = workspaceManager?.getWorkspace(childId);
  const parentWorkspace = workspaceManager?.getWorkspace(parentId);

  if (!childWorkspace || !parentWorkspace) {
    // No workspace to consolidate, just terminate
    await agentManager.terminate(childId, "parent_stopped");
    return { success: true, merged: false };
  }

  // 2. Attempt merge
  const mergeResult = await attemptMerge(
    childWorkspace.branch,
    parentWorkspace.branch,
    parentWorkspace.path
  );

  if (mergeResult.conflicts) {
    // 3a. Handle conflict - abort for now
    await abortMerge(parentWorkspace.path);
    await agentManager.terminate(childId, "merge_conflict");
    return { 
      success: false, 
      merged: false, 
      conflicts: mergeResult.conflicts 
    };
  }

  // 4. Success - terminate child
  await agentManager.terminate(childId, "changes_consolidated");
  return { success: true, merged: true };
}
```

